export function vehicleView(product,side,options){const body=vehicleBody(product,options);if(body&&!body.legacy){const view=body.views[side],g=/\/g\//.test(body.art),a=(g?GEN_ART:VEHICLE_ART)[body.id]?.[view?.key];if(!a)return null;const mir=a[7]===1,f='/studio/mockups/'+body.art+'-'+(mir?'driver-side':view.key);return {photo:f+'.webp',mask:f+'-mask.webp',veil:f+'-veil.webp',dark:g?f+'-dark.webp':null,box:[a[0],a[1],a[2],a[8]||a[2]*view.height/view.width],size:[1536,1024],mirror:mir,crop:a.slice(3,7)};}
 const cfg=VEHICLES[product?.id],view=product?.views?.[side];if(!cfg||!view)return null;const base='/studio/mockups/';
 if(view.key==='driver-side'||view.key==='passenger-side')return {photo:base+cfg.name+'.png',mask:base+cfg.name+'-mask.webp',veil:base+cfg.name+'-veil.webp',box:vehicleBox(product),size:[1536,1024],mirror:view.key==='passenger-side',crop:[0,140,1536,800]};
 const v=cfg.views?.[view.key];if(!v)return null;const [x,y,w]=v.box;return {photo:base+v.img+'.webp',mask:base+v.img+'-mask.webp',veil:base+v.img+'-veil.webp',box:[x,y,w,w*view.height/view.width],size:[1536,1024],mirror:false,crop:v.crop};}
